/**
 * Mini Elasmosaurus (Tipo Agua) — Versión Chibi / Cría compañera de dinosaurio.
 * Basado en el arte oficial de Dinosaur King:
 *   assets/dinos/arte/agua/elasmosaurus_der.webp
 *
 * Características anatómicas del Elasmosaurus:
 *   - Legendario plesiosaurio acuático tierno y majestuoso de cuello larguísimo y serpentino.
 *   - Cuerpo fusiforme e hidrodinámico en forma de barril liso y compacto.
 *   - 4 aletas hidrodinámicas con perfil aerodinámico / alar (2 grandes pectorales y 2 pelvianas),
 *     cerradas herméticamente en cúpula dentro del cuerpo (cero huecos).
 *   - Cabecita pequeña e hidrodinámica con hocico estilizado, mandíbula inferior articulada
 *     y finos dientecitos cónicos de aguja entrelazados para pescar.
 *   - Cola corta afilada como timón estabilizador.
 *   - Lomo y cuello continuo perfectamente orgánico sin cortes ni paredes verticales.
 *   - Malla 100% cerrada y hermética (cero huecos, extremidades con cúpulas internas).
 *   - Proyección lateral de la textura oficial con azul petróleo / verde azulado marino (#306070),
 *     vientre crema plateado suave (#eef3f7) y ojos anime de agua turquesa.
 *   - Esqueleto y animaciones submarinas fluidas (Reposo flotando, Nadar / vuelo subacuático, Rugir / Ataque marino).
 */
registrarMalla({
  id: "mini_elasmosaurus",
  categoria: "mini dino",
  nombre: "Mini Elasmosaurus (Agua)",
  icono: "🌊",
  origen: "assets/dinos/arte/agua/elasmosaurus_der.webp",

  construir(M) {
    const g = new THREE.Group();
    const LADOS = [-1, 1];
    const L = (s) => (s > 0 ? "I" : "D");
    const V = (x, y, z) => new THREE.Vector3(x, y, z);
    const grad = Math.PI / 180;
    const cr = (p0, p1, p2, p3, t) => 0.5 * ((2 * p1) + (-p0 + p2) * t
      + (2 * p0 - 5 * p1 + 4 * p2 - p3) * t * t + (-p0 + 3 * p1 - 3 * p2 + p3) * t * t * t);

    // ---------------- UTILIDADES GEOMÉTRICAS ----------------
    const suave = (a, b, x) => {
      const t = Math.max(0, Math.min(1, (x - a) / (b - a)));
      return t * t * (3 - 2 * t);
    };

    function rejilla(pos, cols, rows, nombre) {
      const idx = [];
      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          const a = r * (cols + 1) + c;
          const b = a + cols + 1;
          idx.push(a, b, a + 1, b, b + 1, a + 1);
        }
      }
      const geo = new THREE.BufferGeometry();
      geo.setAttribute("position", new THREE.Float32BufferAttribute(pos, 3));
      geo.setIndex(idx);
      return M.pieza(geo, nombre, cols, rows);
    }

    function bloque(x, y, z, rx, ry, rz, curva = 0.5, nombre = "Bloque", segA = 14, segB = 10) {
      const sW = M.seg(segA, 8);
      const sH = M.seg(segB, 6);
      const geo = new THREE.SphereGeometry(1, sW, sH);
      const pos = geo.attributes.position;
      for (let i = 0; i < pos.count; i++) {
        let px = pos.getX(i), py = pos.getY(i), pz = pos.getZ(i);
        const d = Math.pow(Math.abs(px), 2.5) + Math.pow(Math.abs(py), 2.5) + Math.pow(Math.abs(pz), 2.5);
        const f = 1 / Math.pow(d, 1 / 2.5);
        px = (px * (1 - curva) + (px * f) * curva) * rx;
        py = (py * (1 - curva) + (py * f) * curva) * ry;
        pz = (pz * (1 - curva) + (pz * f) * curva) * rz;
        pos.setXYZ(i, px, py, pz);
      }
      geo.translate(x, y, z);
      return M.pieza(geo, nombre, sW, sH);
    }

    function punta(camino, radio, nombre, segL = 12, segR = 10) {
      const c = M.curva(camino);
      const tSeg = M.seg(segL, 8);
      const rSeg = M.seg(segR, 6);
      const geo = new THREE.TubeGeometry(c, tSeg, 1, rSeg, false);
      const pos = geo.attributes.position;
      const P = new THREE.Vector3();
      for (let i = 0; i <= tSeg; i++) {
        const t = i / tSeg;
        c.getPointAt(t, P);
        const r = radio * Math.max(0.001, 1 - t * 0.96);
        for (let j = 0; j <= rSeg; j++) {
          const k = i * (rSeg + 1) + j;
          pos.setXYZ(k,
            P.x + (pos.getX(k) - P.x) * r,
            P.y + (pos.getY(k) - P.y) * r,
            P.z + (pos.getZ(k) - P.z) * r
          );
        }
      }
      return M.coserNormales(M.pieza(geo, nombre, rSeg, tSeg));
    }

    function almendra(rx, ry, rz, nombre = "Almendra", segA = 16, segB = 12) {
      const sW = M.seg(segA, 10);
      const sH = M.seg(segB, 8);
      const geo = new THREE.SphereGeometry(1, sW, sH);
      const pos = geo.attributes.position;
      for (let i = 0; i < pos.count; i++) {
        let px = pos.getX(i), py = pos.getY(i), pz = pos.getZ(i);
        const k = 1 - Math.abs(px) * 0.35;
        px *= rx * 1.05;
        py *= ry * k;
        pz *= rz * k;
        pos.setXYZ(i, px, py, pz);
      }
      return M.pieza(geo, nombre, sW, sH);
    }

    // ---------------- 1. CUERPO CONTINUO FUSIFORME 100% CERRADO ----------------
    // Eje longitudinal hidrodinámico con cuello serpentino largo y transición orgánica:
    // [z, y, semiancho, altoHaciaArriba, altoHaciaAbajo, forma]
    const EJE = [
      [-0.68, 0.320, 0.000, 0.000, 0.000, 2.0],  // Punta de la colita timón cerrada
      [-0.62, 0.325, 0.035, 0.040, 0.035, 2.0],  // Cola posterior
      [-0.50, 0.330, 0.065, 0.075, 0.065, 2.1],  // Cola media
      [-0.35, 0.340, 0.115, 0.115, 0.105, 2.2],  // Base de la cola
      [-0.20, 0.350, 0.175, 0.155, 0.145, 2.4],  // Pelvis y aletas traseras
      [-0.05, 0.360, 0.205, 0.175, 0.165, 2.5],  // Torso fusiforme hidrodinámico
      [ 0.10, 0.360, 0.185, 0.165, 0.155, 2.4],  // Pecho y aletas delanteras
      [ 0.22, 0.390, 0.135, 0.135, 0.125, 2.3],  // Base del cuello (transición gradual continua)
      [ 0.32, 0.480, 0.095, 0.095, 0.090, 2.2],  // Cuello en curvatura suave
      [ 0.42, 0.620, 0.075, 0.080, 0.075, 2.1],  // Cuello medio
      [ 0.50, 0.760, 0.068, 0.072, 0.068, 2.1],  // Cuello alto
      [ 0.58, 0.850, 0.062, 0.066, 0.062, 2.1],  // Nuca
      [ 0.64, 0.840, 0.065, 0.060, 0.052, 2.3],  // Cráneo chibi
      [ 0.70, 0.820, 0.050, 0.045, 0.038, 2.2],  // Frente del hocico
      [ 0.75, 0.800, 0.032, 0.028, 0.024, 2.1],  // Punta del hocico
      [ 0.77, 0.790, 0.000, 0.000, 0.000, 2.0]   // Cierre hermético en domo redondeado
    ];

    const ejeCurva = new THREE.CatmullRomCurve3(EJE.map(([z, y]) => V(0, y, z)), false, "centripetal");
    ejeCurva.arcLengthDivisions = 1600;
    const LARGO = ejeCurva.getLength();

    function seccion(u) {
      const f = ejeCurva.getUtoTmapping(u) * (EJE.length - 1);
      const i = Math.min(EJE.length - 2, Math.floor(f));
      const t = f - i;
      const a = EJE[Math.max(0, i - 1)];
      const b = EJE[i];
      const c = EJE[i + 1];
      const d = EJE[Math.min(EJE.length - 1, i + 2)];
      return [2, 3, 4, 5].map((j) => Math.max(0, cr(a[j], b[j], c[j], d[j], t)));
    }

    const X = V(1, 0, 0);
    function marcoEje(u) {
      const P = ejeCurva.getPointAt(u);
      const T = ejeCurva.getTangentAt(u);
      // Suavizamos la inclinación en Y-Z para que las rebanadas desciendan de forma 100% orgánica
      // sin pliegues hacia atrás ni cortes en la curvatura del cuello:
      const ang = Math.atan2(T.y, T.z);
      const angSuave = ang * 0.28;
      const U = V(0, Math.cos(angSuave), -Math.sin(angSuave));
      return { P, T, U };
    }

    function uCercano(p, desde = 0, hasta = 1) {
      let mejor = desde;
      let dMin = Infinity;
      for (let k = 0; k <= 400; k++) {
        const u = desde + (hasta - desde) * (k / 400);
        const d = ejeCurva.getPointAt(u).distanceToSquared(p);
        if (d < dMin) { dMin = d; mejor = u; }
      }
      return mejor;
    }

    // Malla continua de ultra-alta densidad
    const COLS = M.seg(96, 28);
    const FILAS = M.seg(480, 80);
    const cuerpo = (() => {
      const pos = [];
      for (let r = 0; r <= FILAS; r++) {
        const u = r / FILAS;
        const { P, U } = marcoEje(u);
        const [w, hA, hB, p] = seccion(u);
        const ex = 2 / p;
        const z = P.z;

        // Quilla dorsal baja y suave para estabilidad acuática
        const quilla = (z > -0.55 && z < 0.20) ? 0.012 * Math.sin((z + 0.55) / 0.75 * Math.PI) : 0;

        for (let c = 0; c <= COLS; c++) {
          const fi = Math.PI + (c / COLS) * Math.PI * 2;
          const s = Math.sin(fi);
          const co = Math.cos(fi);
          const remateQuilla = co > 0.85 ? quilla * Math.pow((co - 0.85) / 0.15, 1.8) : 0;

          const lx = w * Math.sign(s) * Math.pow(Math.abs(s), ex);
          const ly = ((co >= 0 ? hA : hB) + remateQuilla) * Math.sign(co) * Math.pow(Math.abs(co), ex);
          const pto = P.clone().addScaledVector(X, lx).addScaledVector(U, ly);
          pos.push(pto.x, pto.y, pto.z);
        }
      }
      return M.coserNormales(rejilla(pos, COLS, FILAS, "CuerpoElasmosaurus"));
    })();

    // ---------------- 2. ESQUELETO Y RIGGING ACUÁTICO ----------------
    const ALETA_DEL_X = 0.17;
    const ALETA_TRAS_X = 0.16;

    const HUESOS = [
      ["Raiz", null, 0, 0, 0],
      ["Cadera", "Raiz", 0, 0.35, -0.15],
      ["Cola1", "Cadera", 0, 0.34, -0.32],
      ["Cola2", "Cola1", 0, 0.33, -0.48],
      ["Cola3", "Cola2", 0, 0.32, -0.62],
      ["Pecho", "Cadera", 0, 0.36, 0.12],
      ["Cuello1", "Pecho", 0, 0.44, 0.28],
      ["Cuello2", "Cuello1", 0, 0.56, 0.38],
      ["Cuello3", "Cuello2", 0, 0.70, 0.46],
      ["Cuello4", "Cuello3", 0, 0.82, 0.54],
      ["Cabeza", "Cuello4", 0, 0.84, 0.65],
      ["Mandibula", "Cabeza", 0, 0.80, 0.63],
      ...LADOS.flatMap((s) => [
        // Aletas pectorales (delanteras)
        ["AletaDel" + L(s), "Pecho", s * ALETA_DEL_X, 0.33, 0.12],
        ["AletaPuntaDel" + L(s), "AletaDel" + L(s), s * (ALETA_DEL_X + 0.15), 0.22, 0.02],
        // Aletas pelvianas (traseras)
        ["AletaTras" + L(s), "Cadera", s * ALETA_TRAS_X, 0.33, -0.20],
        ["AletaPuntaTras" + L(s), "AletaTras" + L(s), s * (ALETA_TRAS_X + 0.12), 0.24, -0.30]
      ])
    ];

    const hueso = {};
    HUESOS.forEach(([nombre, padre, x, y, z]) => {
      const b = new THREE.Bone();
      b.name = "Hueso" + nombre;
      b.userData.reposo = V(x, y, z);
      const p = padre ? hueso[padre] : null;
      b.position.set(x, y, z).sub(p ? p.userData.reposo : V(0, 0, 0));
      (p || g).add(b);
      hueso[nombre] = b;
    });
    g.updateMatrixWorld(true);
    const colgar = (nombre, obj) => {
      const h = typeof nombre === "string" ? hueso[nombre] : nombre;
      if (!h || !obj) return obj;
      h.attach(obj);
      return obj;
    };

    // Vinculación suave de la piel del cuerpo continuo a los huesos
    const uH = (n, d1 = 0.2, d2 = 1) => uCercano(hueso[n].userData.reposo, d1, d2);
    const uCola3 = uCercano(hueso.Cola3.userData.reposo, 0, 0.25);
    const uCola2 = uCercano(hueso.Cola2.userData.reposo, 0.05, 0.35);

    const TRAMOS = [
      [0, "Cola3"],
      [uCola3, "Cola2"],
      [uCola2, "Cola1"],
      [uH("Cola1", 0.10, 0.40), "Cadera"],
      [uH("Pecho", 0.30, 0.55), "Pecho"],
      [uH("Cuello1", 0.45, 0.65), "Cuello1"],
      [uH("Cuello2", 0.55, 0.75), "Cuello2"],
      [uH("Cuello3", 0.65, 0.85), "Cuello3"],
      [uH("Cuello4", 0.75, 0.92), "Cuello4"],
      [uH("Cabeza", 0.85, 1.00), "Cabeza"]
    ];

    const MEZCLA = 0.20 / LARGO;
    function pesosTramos(u, tramos, mezcla) {
      let k = 0;
      while (k + 1 < tramos.length && u >= tramos[k + 1][0]) k++;
      const res = [[hueso[tramos[k][1]], 1]];
      if (k + 1 < tramos.length) {
        const w = suave(-mezcla, mezcla, u - tramos[k + 1][0]);
        if (w > 0) { res[0][1] = 1 - w; res.push([hueso[tramos[k + 1][1]], w]); }
      }
      if (k > 0) {
        const w = 1 - suave(-mezcla, mezcla, u - tramos[k][0]);
        if (w > 0) { res[0][1] *= 1 - w; res.push([hueso[tramos[k - 1][1]], w]); }
      }
      return res;
    }

    g.add(cuerpo);
    M.pielConHuesos(cuerpo, g, (i) => pesosTramos(Math.floor(i / (COLS + 1)) / FILAS, TRAMOS, MEZCLA));

    // ---------------- 3. ALETAS HIDRODINÁMICAS HERMÉTICAS 100% CERRADAS ----------------
    // Generador de aletas alares fusiformes con cúpula interna embutida en el cuerpo
    function aletaHidrodinamica(s, camino, radiosW, radiosH, huesosAleta, nombre) {
      const curva = M.curva(camino);
      const tSeg = M.seg(24, 10);
      const rSeg = M.seg(24, 10);
      const geo = new THREE.TubeGeometry(curva, tSeg, 1, rSeg, false);
      const pos = geo.attributes.position;
      const P = new THREE.Vector3();

      for (let i = 0; i <= tSeg; i++) {
        const t = i / tSeg;
        curva.getPointAt(t, P);
        let rw = M.interp(radiosW, t);
        let rh = M.interp(radiosH, t);

        // Cierre de cúpula interna hermética en la raíz dentro del cuerpo
        if (t < 0.20) {
          const cap = Math.sqrt(Math.max(0, 1 - Math.pow(1 - t / 0.20, 2)));
          rw *= cap;
          rh *= cap;
        }
        // Cierre cónico suave en el extremo de la pala
        if (t > 0.85) {
          const tap = Math.sqrt(Math.max(0, 1 - Math.pow((t - 0.85) / 0.15, 2)));
          rw *= tap;
          rh *= tap;
        }

        for (let j = 0; j <= rSeg; j++) {
          const k = i * (rSeg + 1) + j;
          const fi = (j / rSeg) * Math.PI * 2;
          // Perfil elíptico hidrodinámico (ancho en horizontal, delgado en vertical)
          const lx = (pos.getX(k) - P.x) * rw;
          const ly = (pos.getY(k) - P.y) * rh;
          const lz = (pos.getZ(k) - P.z) * rw * 0.85;

          pos.setXYZ(k, P.x + lx, P.y + ly, P.z + lz);
        }
      }

      const malla = M.coserNormales(M.pieza(geo, nombre, rSeg, tSeg));
      g.add(malla);

      const tramos = [
        [0, huesosAleta[0]],
        [0.55, huesosAleta[1]]
      ];
      M.pielConHuesos(malla, g, (i) => pesosTramos(Math.floor(i / (rSeg + 1)) / tSeg, tramos, 0.18));
      return malla;
    }

    LADOS.forEach((s) => {
      // Aleta pectoral delantera (mayor envergadura y propulsión alar)
      const xDel = s * ALETA_DEL_X;
      aletaHidrodinamica(s,
        [
          [s * (ALETA_DEL_X - 0.05), 0.35, 0.12],
          [xDel, 0.33, 0.11],
          [s * (ALETA_DEL_X + 0.14), 0.24, 0.03],
          [s * (ALETA_DEL_X + 0.28), 0.14, -0.06],
          [s * (ALETA_DEL_X + 0.38), 0.07, -0.16]
        ],
        [[0, 0.065], [0.30, 0.082], [0.65, 0.072], [1, 0.035]],
        [[0, 0.045], [0.30, 0.026], [0.65, 0.016], [1, 0.007]],
        ["AletaDel" + L(s), "AletaPuntaDel" + L(s)], "AletaPectoral");

      // Aleta pelviana trasera (timón y empuje secundario)
      const xTras = s * ALETA_TRAS_X;
      aletaHidrodinamica(s,
        [
          [s * (ALETA_TRAS_X - 0.04), 0.34, -0.18],
          [xTras, 0.32, -0.19],
          [s * (ALETA_TRAS_X + 0.12), 0.25, -0.27],
          [s * (ALETA_TRAS_X + 0.22), 0.17, -0.36],
          [s * (ALETA_TRAS_X + 0.30), 0.11, -0.45]
        ],
        [[0, 0.055], [0.30, 0.068], [0.65, 0.056], [1, 0.028]],
        [[0, 0.038], [0.30, 0.022], [0.65, 0.014], [1, 0.006]],
        ["AletaTras" + L(s), "AletaPuntaTras" + L(s)], "AletaPelvica");
    });

    // ---------------- 4. CABEZA CHIBI, MANDÍBULA ARTICULADA Y DIENTES DE AGUJA ----------------
    // Mandíbula inferior pequeña e hidrodinámica
    const MAND_PERFIL = [
      // [z, y, semiancho, alto, forma]
      [0.60, 0.812, 0.058, 0.024, 2.2],  // Comisura trasera articulada
      [0.66, 0.804, 0.052, 0.022, 2.2],  // Mandíbula media
      [0.71, 0.796, 0.040, 0.018, 2.1],  // Hacia el mentón
      [0.75, 0.788, 0.025, 0.014, 2.0],  // Barbilla delantera
      [0.77, 0.782, 0.000, 0.000, 2.0]   // Punta cerrada
    ];

    const colsMand = M.seg(48, 20);
    const filasMand = M.seg(32, 16);
    const posMand = [];

    for (let r = 0; r <= filasMand; r++) {
      const t = r / filasMand;
      const f = t * (MAND_PERFIL.length - 1);
      const i = Math.min(MAND_PERFIL.length - 2, Math.floor(f));
      const e = f - i;
      const a = MAND_PERFIL[Math.max(0, i - 1)];
      const b = MAND_PERFIL[i];
      const c = MAND_PERFIL[i + 1];
      const d = MAND_PERFIL[Math.min(MAND_PERFIL.length - 1, i + 2)];

      const z = cr(a[0], b[0], c[0], d[0], e);
      const y = cr(a[1], b[1], c[1], d[1], e);
      const w = Math.max(0, cr(a[2], b[2], c[2], d[2], e));
      const h = Math.max(0, cr(a[3], b[3], c[3], d[3], e));
      const p = Math.max(1.8, cr(a[4], b[4], c[4], d[4], e));
      const ex = 2 / p;

      for (let col = 0; col <= colsMand; col++) {
        const fi = Math.PI + (col / colsMand) * Math.PI * 2;
        const sx = Math.sin(fi);
        const cy = Math.cos(fi);
        const hActual = cy > 0 ? h * 0.40 : h;
        const px = w * Math.sign(sx) * Math.pow(Math.abs(sx), ex);
        const py = y + hActual * cy;
        posMand.push(px, py, z);
      }
    }
    colgar("Mandibula", M.coserNormales(rejilla(posMand, colsMand, filasMand, "MandibulaBebé")));

    // Lengua suave rosada en el piso de la mandíbula
    colgar("Mandibula", bloque(0, 0.796, 0.68, 0.022, 0.008, 0.065, 0.6, "Lengua"));

    // Dientecitos finos de aguja entrelazados característicos de Elasmosaurus
    LADOS.forEach((s) => {
      // Dientes inferiores
      [0.64, 0.67, 0.70, 0.73, 0.75].forEach((z, idx) => {
        const wTeeth = 0.048 - idx * 0.006;
        const xTeeth = s * wTeeth;
        colgar("Mandibula", punta([[xTeeth, 0.802, z], [xTeeth, 0.814, z + 0.002]], 0.0035, "DienteInferior", 8, 6));
      });

      // Dientes superiores
      [0.655, 0.685, 0.715, 0.745, 0.762].forEach((z, idx) => {
        const wTeeth = 0.052 - idx * 0.006;
        const xTeeth = s * wTeeth;
        colgar("Cabeza", punta([[xTeeth, 0.816, z], [xTeeth, 0.804, z + 0.002]], 0.0038, "DienteSuperior", 8, 6));
      });

      // Labio superior suave
      const labioPuntos = [
        [s * 0.062, 0.822, 0.62],
        [s * 0.054, 0.816, 0.67],
        [s * 0.042, 0.810, 0.71],
        [s * 0.026, 0.805, 0.74],
        [s * 0.005, 0.802, 0.76]
      ];
      colgar("Cabeza", M.tubo(labioPuntos, 0.0055, 0.004, { segLargo: 24, segRadio: 10, nombre: "LabioSuperior" }));
    });

    // Fosas nasales en lo alto del hocico
    LADOS.forEach((s) => {
      colgar("Cabeza", bloque(s * 0.018, 0.842, 0.71, 0.005, 0.004, 0.006, 0.4, "FosaNasal", 10, 8));
    });

    // Ojos anime grandes y expresivos de criatura marina
    LADOS.forEach((s) => {
      const ojoGrupo = new THREE.Group();
      ojoGrupo.position.set(s * 0.058, 0.865, 0.64);
      ojoGrupo.rotation.y = s * 0.42;

      // Córnea blanca
      ojoGrupo.add(almendra(0.042, 0.038, 0.012, "OjoBlanco"));

      // Iris azul turquesa / cyan marino profundo
      ojoGrupo.add(bloque(s * 0.003, 0, 0.005, 0.030, 0.030, 0.007, 1, "IrisAgua"));

      // Pupila profunda
      ojoGrupo.add(bloque(s * 0.003, -0.001, 0.010, 0.016, 0.018, 0.005, 1, "Pupila"));

      // Brillos especulares
      ojoGrupo.add(bloque(-s * 0.010, 0.011, 0.013, 0.011, 0.011, 0.004, 1, "BrilloOjo"));
      ojoGrupo.add(bloque(s * 0.010, -0.009, 0.012, 0.006, 0.006, 0.003, 1, "BrilloOjoPequeno"));

      // Párpados finos
      ojoGrupo.add(M.tubo([
        [-0.038, 0.005, 0.005],
        [0, 0.036, 0.010],
        [0.038, 0.005, 0.005]
      ], 0.004, 0.003, { segLargo: 10, segRadio: 8, nombre: "ParpadoSuperior" }));

      ojoGrupo.add(M.tubo([
        [-0.035, -0.005, 0.005],
        [0, -0.033, 0.008],
        [0.035, -0.005, 0.005]
      ], 0.0035, 0.0028, { segLargo: 10, segRadio: 8, nombre: "ParpadoInferior" }));

      colgar("Cabeza", ojoGrupo);
    });

    // ---------------- 5. PINTURA: PROYECCIÓN Y COLORES DE ELASMOSAURUS_DER.WEBP ----------------
    const TEXTURA = this.textura;
    const proyectar = M.proyeccion(TEXTURA, 0.92);

    const C_BASE_MARINO = new THREE.Color(0x356575);
    const C_CREMA_VIENTRE = new THREE.Color(0xeef4f8);
    const C_LENGUA = new THREE.Color(0xce6d5e);
    const MARFIL = new THREE.Color(0xfbf6ea);
    const cColor = new THREE.Color();

    // Pintar cuerpo cerrado con proyección lateral y vientre crema plateado continuo
    M.pintar(cuerpo, (i, p) => {
      proyectar(p.z, p.y, cColor);

      // Si cae en zona transparente o negra del fondo, salvaguarda con color base marino
      if (cColor.r < 0.08 && cColor.g < 0.08 && cColor.b < 0.08) {
        cColor.copy(C_BASE_MARINO);
      }

      const u = Math.floor(i / (COLS + 1)) / FILAS;
      const cIdx = i % (COLS + 1);
      const fi = Math.PI + (cIdx / COLS) * Math.PI * 2;
      const co = Math.cos(fi);

      // Pecho, garganta y vientre inferior de color crema plateado suave
      if (co < 0.20 && p.y < 0.65 && u > 0.08 && u < 0.92) {
        const factorVientre = Math.pow((0.20 - co) / 1.20, 1.2) * (1 - Math.min(1, Math.abs(p.x) / 0.18));
        cColor.lerp(C_CREMA_VIENTRE, Math.min(1, factorVientre * 0.88));
      }

      return cColor;
    }, g);

    // Pintar piezas secundarias
    const COLOR_PIEZAS = {
      mandibula: 0x3d6e7f,
      labio: 0x274a57,
      fosaNasal: 0x1a333d,
      parpado: 0x2f5766,
      iris: 0x06b6d4,
      pupila: 0x0a1926,
      brillo: 0xffffff,
      ojoBlanco: 0xfefcf9
    };

    const piezas = [];
    g.traverse((o) => { if (o.isMesh && o !== cuerpo) piezas.push(o); });

    piezas.forEach((o) => {
      if (/^Diente/.test(o.name)) return M.pintar(o, () => MARFIL, g);
      if (o.name === "Lengua") return M.pintar(o, () => C_LENGUA, g);
      if (o.name === "OjoBlanco") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.ojoBlanco), g);
      if (o.name === "IrisAgua") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.iris), g);
      if (o.name === "Pupila") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.pupila), g);
      if (/^BrilloOjo/.test(o.name)) return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.brillo), g);
      if (/^Parpado/.test(o.name)) return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.parpado), g);
      if (o.name === "LabioSuperior") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.labio), g);
      if (o.name === "FosaNasal") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.fosaNasal), g);

      if (/^Aleta/.test(o.name)) {
        return M.pintar(o, (i, p) => {
          proyectar(p.z, p.y, cColor);
          if (cColor.r < 0.08 && cColor.g < 0.08 && cColor.b < 0.08) cColor.copy(C_BASE_MARINO);
          if (p.y < 0.25) cColor.lerp(C_CREMA_VIENTRE, 0.40);
          return cColor;
        }, g);
      }

      if (o.name === "MandibulaBebé") {
        return M.pintar(o, (i, p) => {
          proyectar(p.z, p.y, cColor);
          if (cColor.r < 0.12 && cColor.g < 0.12 && cColor.b < 0.12) cColor.setHex(COLOR_PIEZAS.mandibula);
          if (p.y < 0.810) cColor.lerp(C_CREMA_VIENTRE, suave(0.810, 0.785, p.y) * 0.82);
          return cColor;
        }, g);
      }
    });

    // ---------------- 6. ANIMACIONES ACUÁTICAS CHIBI (THREE.AnimationMixer) ----------------
    const q = new THREE.Quaternion();
    const eu = new THREE.Euler();
    function giro(nombre, dur, fn, n = 32) {
      const tiempos = [];
      const valores = [];
      for (let i = 0; i <= n; i++) {
        const [x, y, z] = fn(i / n);
        eu.set(x * grad, y * grad, z * grad);
        q.setFromEuler(eu);
        tiempos.push(i * (dur / n));
        valores.push(q.x, q.y, q.z, q.w);
      }
      return new THREE.QuaternionKeyframeTrack("Hueso" + nombre + ".quaternion", tiempos, valores);
    }

    function sube(nombre, dur, fn, n = 32) {
      const tiempos = [];
      const valores = [];
      const [x0, y0, z0] = hueso[nombre].position.toArray();
      for (let i = 0; i <= n; i++) {
        tiempos.push(i * (dur / n));
        valores.push(x0, y0 + fn(i / n), z0);
      }
      return new THREE.VectorKeyframeTrack("Hueso" + nombre + ".position", tiempos, valores);
    }

    const sen = (t, c = 1) => Math.sin(t * Math.PI * 2 * c);
    const cos = (t, c = 1) => Math.cos(t * Math.PI * 2 * c);

    // Reposo: flotación marina apacible, mecida serpentina dulce de cuello y aletas
    const dR = 3.0;
    const reposo = new THREE.AnimationClip("Reposo", dR, [
      sube("Cadera", dR, (t) => 0.012 * sen(t)),
      giro("Cadera", dR, (t) => [1.0 * sen(t), 0, 1.5 * cos(t)]),
      giro("Pecho", dR, (t) => [-1.0 * sen(t), 0, -1.5 * cos(t)]),
      giro("Cuello1", dR, (t) => [-1.2 * sen(t), 1.5 * sen(t), 0]),
      giro("Cuello2", dR, (t) => [1.0 * sen(t), 2.2 * sen(t), 0]),
      giro("Cuello3", dR, (t) => [-1.5 * sen(t), 2.0 * sen(t), 0]),
      giro("Cuello4", dR, (t) => [1.2 * sen(t), -1.8 * sen(t), 0]),
      giro("Cabeza", dR, (t) => [1.5 * sen(t), -1.5 * sen(t), 1.2 * cos(t)]),
      giro("Cola1", dR, (t) => [0, 5 * sen(t), 0]),
      giro("Cola2", dR, (t) => [0, 10 * sen(t), 0]),
      giro("Cola3", dR, (t) => [0, 16 * sen(t), 0]),
      // Remado suave de aletas para mantener flotación
      giro("AletaDelI", dR, (t) => [4 * sen(t), 0, 6 * cos(t)]),
      giro("AletaDelD", dR, (t) => [4 * sen(t), 0, -6 * cos(t)]),
      giro("AletaTrasI", dR, (t) => [-3 * sen(t), 0, 4 * cos(t)]),
      giro("AletaTrasD", dR, (t) => [-3 * sen(t), 0, -4 * cos(t)])
    ]);

    // Caminar / Nadar: majestuoso vuelo subacuático (aleteo sincronizado en ocho y cuello ondeante)
    const dC = 1.4;
    const BRACEO = 16;
    const caminar = new THREE.AnimationClip("Caminar", dC, [
      sube("Cadera", dC, (t) => 0.018 * sen(t, 2)),
      giro("Cadera", dC, (t) => [2 * sen(t), 0, 3 * cos(t)]),
      giro("Pecho", dC, (t) => [-2 * sen(t), 0, -3 * cos(t)]),
      giro("Cuello1", dC, (t) => [2.5 * sen(t, 2), 3 * sen(t), 0]),
      giro("Cuello2", dC, (t) => [-1.8 * sen(t, 2), 4 * sen(t), 0]),
      giro("Cuello3", dC, (t) => [2.2 * sen(t, 2), -3 * sen(t), 0]),
      giro("Cuello4", dC, (t) => [-1.5 * sen(t, 2), -2 * sen(t), 0]),
      giro("Cabeza", dC, (t) => [1.0 * sen(t, 2), -2 * sen(t), 1.5 * sen(t)]),
      giro("Cola1", dC, (t) => [0, 8 * sen(t), 0]),
      giro("Cola2", dC, (t) => [0, 16 * sen(t), 0]),
      giro("Cola3", dC, (t) => [0, 24 * sen(t), 0]),
      // Vuelo subacuático de las aletas en brazada marina
      giro("AletaDelI", dC, (t) => [-BRACEO * cos(t), 6 * sen(t), BRACEO * 0.8 * sen(t)]),
      giro("AletaDelD", dC, (t) => [-BRACEO * cos(t), -6 * sen(t), -BRACEO * 0.8 * sen(t)]),
      giro("AletaTrasI", dC, (t) => [BRACEO * 0.7 * cos(t), -4 * sen(t), -BRACEO * 0.6 * sen(t)]),
      giro("AletaTrasD", dC, (t) => [BRACEO * 0.7 * cos(t), 4 * sen(t), BRACEO * 0.6 * sen(t)])
    ]);

    // Rugir / Ataque acuático: arco serpentino majestuoso, impulso de aletas y llamada marina
    const dG = 2.0;
    const alzar = [[0, 0], [0.25, 1], [0.75, 1], [1, 0]];
    const abrirBoca = [[0, 0], [0.25, 0], [0.42, 1], [0.72, 1], [0.88, 0], [1, 0]];
    const rugir = new THREE.AnimationClip("Rugir", dG, [
      sube("Cadera", dG, (t) => 0.035 * M.interp(alzar, t)),
      giro("Cadera", dG, (t) => [-8 * M.interp(alzar, t), 0, 0]),
      giro("Pecho", dG, (t) => [-12 * M.interp(alzar, t), 0, 0]),
      giro("Cuello1", dG, (t) => [8 * M.interp(alzar, t), 0, 0]),
      giro("Cuello2", dG, (t) => [-16 * M.interp(alzar, t), 0, 0]),
      giro("Cuello3", dG, (t) => [-12 * M.interp(alzar, t), 0, 0]),
      giro("Cuello4", dG, (t) => [10 * M.interp(alzar, t), 0, 0]),
      giro("Cabeza", dG, (t) => [8 * M.interp(alzar, t), 0, 0]),
      giro("Mandibula", dG, (t) => [26 * M.interp(abrirBoca, t), 0, 0]),
      giro("Cola1", dG, (t) => [4 * M.interp(alzar, t), 10 * sen(t, 2), 0]),
      giro("Cola2", dG, (t) => [8 * M.interp(alzar, t), 20 * sen(t, 2), 0]),
      giro("Cola3", dG, (t) => [12 * M.interp(alzar, t), 30 * sen(t, 2), 0]),
      // Impulso hacia atrás de las aletas para embestir
      giro("AletaDelI", dG, (t) => [24 * M.interp(alzar, t), 0, 18 * M.interp(alzar, t)]),
      giro("AletaDelD", dG, (t) => [24 * M.interp(alzar, t), 0, -18 * M.interp(alzar, t)]),
      giro("AletaTrasI", dG, (t) => [16 * M.interp(alzar, t), 0, 12 * M.interp(alzar, t)]),
      giro("AletaTrasD", dG, (t) => [16 * M.interp(alzar, t), 0, -12 * M.interp(alzar, t)])
    ]);

    g.animations = [reposo, caminar, rugir];
    hueso.Raiz.userData.esqueleto = HUESOS.map(([nombre]) => "Hueso" + nombre);

    return g;
  },

  // Imagen de referencia reducida ×2, sin tinta (RGB en base64) para proyectar colores fieles de elasmosaurus_der.webp:
  textura: {
    w: 260, h: 170, k: 2, esc: 0.00295, x0: 260, y0: 345,
    datos: ""
  }
});
